{{!-- Styling parameters: class, contentClass, linkClass, buttonClass --}}
{{#with this as |ghostcnStyles|}}
<div class="ghcn-announcement{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" data-ghcn-announcement data-variant="{{#match variant "secondary"}}secondary{{else}}{{#match variant "outline"}}outline{{else}}default{{/match}}{{/match}}" data-storage-key="{{#if storageKey}}{{storageKey}}{{else}}default{{/if}}" role="region" aria-label="Announcement">
  <div class="ghcn-announcement__inner ghcn-container">
    <p class="ghcn-announcement__content{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}">
      <span>{{#if text}}{{text}}{{else}}New issue out now — explore the latest stories.{{/if}}</span>
      {{#if href}}<a class="ghcn-announcement__link{{#if ghostcnStyles.linkClass}} {{ghostcnStyles.linkClass}}{{/if}}" href="{{href}}"{{#if dataPortal}} data-portal="{{dataPortal}}"{{/if}}>{{#if linkText}}{{linkText}}{{else}}Learn more{{/if}} <span aria-hidden="true">&rarr;</span></a>{{/if}}
    </p>
    {{#unless hideDismiss}}
    <button type="button" class="ghcn-announcement__dismiss{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" data-announcement-dismiss aria-label="Dismiss announcement">
      <svg aria-hidden="true" viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round"><path d="M4 4l8 8M12 4l-8 8"/></svg>
    </button>
    {{/unless}}
  </div>
</div>
{{/with}}

.ghcn-announcement { box-sizing: border-box; width: 100%; background: var(--primary); color: var(--primary-foreground); border-bottom: 1px solid transparent; font-family: inherit; font-size: var(--ghcn-text-small, 14px); line-height: 1.4; }
.ghcn-announcement[hidden] { display: none; }
.ghcn-announcement *, .ghcn-announcement *::before, .ghcn-announcement *::after { box-sizing: border-box; }
.ghcn-announcement:where([data-variant="secondary"]) { background: var(--secondary); color: var(--secondary-foreground); border-bottom-color: var(--border); }
.ghcn-announcement:where([data-variant="outline"]) { background: var(--card); color: var(--card-foreground); border-bottom-color: var(--border); }
.ghcn-announcement__inner { display: flex; align-items: center; justify-content: center; gap: 12px; padding-block: 10px; position: relative; }
.ghcn-announcement__content { margin: 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 6px 12px; text-align: center; }
.ghcn-announcement__link { color: inherit; font-weight: 600; text-decoration: underline; text-underline-offset: 3px; white-space: nowrap; }
.ghcn-announcement__link:hover { opacity: 0.85; }
.ghcn-announcement__dismiss { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; flex: 0 0 auto; border: 0; border-radius: var(--ghcn-control-radius, var(--radius, 8px)); background: transparent; color: inherit; cursor: pointer; opacity: 0.8; transition: opacity 150ms ease, background-color 150ms ease; }
.ghcn-announcement__dismiss:hover { opacity: 1; background: color-mix(in srgb, currentColor 12%, transparent); }
.ghcn-announcement:focus-visible, :where(.ghcn-announcement) :focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { .ghcn-announcement__dismiss { transition: none; } }

/* ghostcn announcement bar: dismisses with sessionStorage persistence, repeat-safe. */
(() => {
  function init() {
    document.querySelectorAll('[data-ghcn-announcement]').forEach(bar => {
      if (bar.dataset.ghcnAnnouncementReady) return;
      bar.dataset.ghcnAnnouncementReady = 'true';
      const key = 'ghcn-announcement:' + (bar.dataset.storageKey || 'default');
      try {
        if (sessionStorage.getItem(key) === 'dismissed') { bar.hidden = true; return; }
      } catch {}
      const btn = bar.querySelector('[data-announcement-dismiss]');
      if (!btn) return;
      btn.addEventListener('click', () => {
        bar.hidden = true;
        try { sessionStorage.setItem(key, 'dismissed'); } catch {}
      });
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();
